const demosRoute = createRoute({
  getParentRoute: () => appLayoutRoute,
  path: "/app/demos",
  component: DemosPage,
});

const queueDemoRoute = createRoute({
  getParentRoute: () => appLayoutRoute,
  path: "/app/queue-demo",
  component: QueueDemoPage,
});

const emailDemoRoute = createRoute({
  getParentRoute: () => appLayoutRoute,
  path: "/app/email-demo",
  component: EmailDemoPage,
});

test("the dashboard leads to the developer demos", async ({ page }) => {
  await open(page, "/app/dashboard");
  await page.getByRole("link", { name: "Open demos" }).click();
  await expect(page).toHaveURL(/\/app\/demos$/);
  await expect(
    page.getByRole("heading", { name: "Developer demos" })
  ).toBeVisible();
  await page.getByRole("link", { name: "Open queue demo" }).click();
  await expect(page).toHaveURL(/\/app\/queue-demo$/);
});

it("marks Containers as a demo, never as built", () => {
  expect(FEATURES.find((entry) => entry.id === "containers")?.status).toBe(
    "demo"
  );
});

const tasksRoute = createRoute({
  getParentRoute: () => appLayoutRoute,
  path: "/app/tasks",
  component: TasksPage,
});

test("tasks: the sample board switches to a list and filters", async ({
  page,
}) => {
  await open(page, "/app/tasks");
  await expect(
    page.getByRole("complementary", { name: "Placeholder app" })
  ).toContainText("nothing is saved");
  await expect(page.getByText("6 of 6 tasks")).toBeVisible();
  await page.getByRole("radio", { name: "List" }).click();
  await expect(page.getByRole("grid", { name: "Tasks" })).toBeVisible();
});
